"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface SwitchProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

const styles = stylex.create({
  track: {
    display: "inline-flex",
    boxSizing: "border-box",
    width: {
      default: "4rem",
      [mq.phone]: "4rem",
    },
    height: {
      default: vlak.hit,
      [mq.phone]: vlak.hit,
    },
    minWidth: {
      default: "4rem",
      [mq.phone]: "4rem",
    },
    minHeight: {
      default: vlak.hit,
      [mq.phone]: vlak.hit,
    },
    borderRadius: {
      default: "1.375rem",
      [mq.phone]: "1.375rem",
    },
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: {
      default: vlak.controlBorder,
      [mq.forcedColors]: "ButtonText",
    },
    position: "relative",
    flexShrink: 0,
    padding: 0,
    backgroundColor: "transparent",
    cursor: "pointer",
    transition: {
      default: `background-color ${vlak.duration} ${vlak.ease}, border-color ${vlak.duration} ${vlak.ease}`,
      [mq.reduce]: "none",
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": vlak.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  on: {
    backgroundColor: {
      default: vlak.ink,
      [mq.forcedColors]: "Highlight",
    },
    borderColor: {
      default: vlak.ink,
      [mq.forcedColors]: "Highlight",
    },
    forcedColorAdjust: "none",
  },
  thumb: {
    position: "absolute",
    top: {
      default: "0.15625rem",
      [mq.phone]: "0.15625rem",
    },
    insetInlineStart: {
      default: "0.15625rem",
      [mq.phone]: "0.15625rem",
    },
    width: {
      default: "2.25rem",
      [mq.phone]: "2.25rem",
    },
    height: {
      default: "2.25rem",
      [mq.phone]: "2.25rem",
    },
    borderRadius: {
      default: "50%",
      [mq.phone]: "50%",
    },
    backgroundColor: {
      default: vlak.gray,
      [mq.forcedColors]: "ButtonText",
    },
    forcedColorAdjust: "none",
    transition: {
      default: `transform ${vlak.duration} ${vlak.ease}`,
      [mq.reduce]: "none",
    },
  },
  thumbOn: {
    backgroundColor: {
      default: vlak.paper,
      [mq.forcedColors]: "HighlightText",
    },
    transform: {
      default: "translateX(20px)",
      [mq.phone]: "translateX(20px)",
    },
  },
});

/** A button with role="switch". */
export const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  { checked, defaultChecked, onCheckedChange, className, style, onClick, ...props },
  ref,
) {
  const [inner, setInner] = React.useState(defaultChecked ?? false);
  const isControlled = checked !== undefined;
  const on = isControlled ? checked : inner;
  const sx = rs(["rs-switch", on && "rs-switch-on", className], styles.track, on && styles.on);
  const knob = rs(["rs-switch-thumb", on && "rs-switch-thumb-on"], styles.thumb, on && styles.thumbOn);
  return (
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      className={sx.className}
      style={{ ...sx.style, ...style }}
      onClick={(e) => {
        if (!isControlled) setInner(!on);
        onCheckedChange?.(!on);
        onClick?.(e);
      }}
      {...props}
    >
      <i className={knob.className} style={knob.style} />
    </button>
  );
});

/* ── switch: generated from packages/react/src/components/switch.tsx ── */
.rs-switch{display:inline-flex;box-sizing:border-box;width:4rem;height:var(--hit);min-width:4rem;min-height:var(--hit);border-radius:1.375rem;border-width:1.5px;border-style:solid;border-color:var(--control-border);position:relative;flex-shrink:0;padding:0;background-color:transparent;cursor:pointer;transition:background-color var(--duration) var(--ease), border-color var(--duration) var(--ease)}
.rs-switch:focus-visible{outline-width:2px;outline-style:solid;outline-color:var(--text);outline-offset:2px}
@media (max-width: 640px){.rs-switch{width:4rem;height:var(--hit);min-width:4rem;min-height:var(--hit);border-radius:1.375rem}}
@media (forced-colors: active){.rs-switch{border-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch{transition:none}}
.rs-switch-on{background-color:var(--text);border-color:var(--text);forced-color-adjust:none}
@media (forced-colors: active){.rs-switch-on{background-color:Highlight;border-color:Highlight}}
.rs-switch-thumb{position:absolute;top:0.15625rem;inset-inline-start:0.15625rem;width:2.25rem;height:2.25rem;border-radius:50%;background-color:var(--text-secondary);forced-color-adjust:none;transition:transform var(--duration) var(--ease)}
@media (max-width: 640px){.rs-switch-thumb{top:0.15625rem;inset-inline-start:0.15625rem;width:2.25rem;height:2.25rem;border-radius:50%}}
@media (forced-colors: active){.rs-switch-thumb{background-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch-thumb{transition:none}}
.rs-switch-thumb-on{background-color:var(--bg);transform:translateX(20px)}
@media (forced-colors: active){.rs-switch-thumb-on{background-color:HighlightText}}
@media (max-width: 640px){.rs-switch-thumb-on{transform:translateX(20px)}}

